    void createMETSalesItemSubstitute(ItemId _itemId, ItemId _subsItemId)
    {
        METSalesItemSubstitute    MetSalesItemSubstitute;

        select firstonly MetSalesItemSubstitute
                   where MetSalesItemSubstitute.ItemId == _itemId
                      && MetSalesItemSubstitute.SubstituteItemId == _subsItemId
                      && MetSalesItemSubstitute.InventSiteId == ""
                      && MetSalesItemSubstitute.AccountCode == METSalesItemSubstitutionAccountCodeType::All
                      && MetSalesItemSubstitute.AccountRelation == ""
                      && MetSalesItemSubstitute.SubstitutionCode == METSalesItemSubstitutionCode::Replacement;

        if (!MetSalesItemSubstitute)
        {
            MetSalesItemSubstitute.ItemId = _itemId;
            MetSalesItemSubstitute.SubstituteItemId = _subsItemId;
            MetSalesItemSubstitute.InventSiteId = "";
            MetSalesItemSubstitute.AccountCode = METSalesItemSubstitutionAccountCodeType::All;
            MetSalesItemSubstitute.AccountRelation = "";
            MetSalesItemSubstitute.SubstitutionCode = METSalesItemSubstitutionCode::Replacement;
            MetSalesItemSubstitute.ValidFrom = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            MetSalesItemSubstitute.ValidTo = maxDate();
            MetSalesItemSubstitute.insert();
        }
    }



    void createSalesOrderTypes(METSalesOrderTypeID _salesOrderType)
    {
        METSalesOrderTypes METSalesOrderTypes;
        METSalesOrderTypes = METSalesOrderTypes::find(_salesOrderType, true);

        if (METSalesOrderTypes)
        {
            if (!METSalesOrderTypes.SubstitutesAllowed)
            {
                METSalesOrderTypes.SubstitutesAllowed = NoYes::Yes;
                METSalesOrderTypes.update();
            }
        }
        else
        {
            METSalesOrderTypes.SalesOrderTypeID = _salesOrderType;
            METSalesOrderTypes.Name = "Allow subs";
            METSalesOrderTypes.SubstitutesAllowed = NoYes::Yes;
            METSalesOrderTypes.insert();
        }
    }

    SalesTable createSalesTable(CustAccount _custAccount, METSalesOrderTypeID _salesOrderType, InventDim _inventDim)
    {
        SalesTable localSalesTable;
        NumberSeq           numberSeq;
        numberSeq = NumberSeq::newGetNum(SalesParameters::numRefSalesId(), false, true);

        localSalesTable.SalesId = numberSeq.num();
        localSalesTable.SalesType = SalesType::Sales;
        localSalesTable.SalesStatus = SalesStatus::Backorder;

        localSalesTable.CustAccount = _custAccount;
        localSalesTable.initFromCustTable();

        localSalesTable.InventSiteId = _inventDim.InventSiteId;
        localSalesTable.InventLocationId = _inventDim.InventLocationId;

        localSalesTable.METSalesOrderType = _salesOrderType;

        localSalesTable.ShippingDateRequested = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        localSalesTable.ReceiptDateRequested = localSalesTable.ShippingDateRequested;

        localSalesTable.GUPSkipPricingCalculation = NoYes::Yes;

        if (localSalesTable.validateWrite())
        {
            localSalesTable.insert();
            METSalesTable metSalesTable = METSalesTable::findByRefRecId(localSalesTable.RecId, true);
            metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::IOMSyncCompleted;
            metSalesTable.OrderReleaseDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            metSalesTable.update();
        }

        return localSalesTable;
    }

    void createSalesLine(SalesTable _salesTable, ItemId _itemId)
    {
        SalesLine salesLine;
        salesLine.initFromSalesTable(_salesTable);

        salesLine.SalesId = _salesTable.salesId;
        salesLine.ItemId = _itemId;
        salesLine.SalesUnit = 'EA';
        salesLine.SalesPrice = 10;
        salesLine.SalesQty = 1;
        salesLine.itemIdChanged();

        salesLine.createLine(true, false, false, false, false);

        salesLine.selectForUpdate();
        salesLine.SalesPrice = 10;
        salesLine.update();

        METSalesLine metSalesLine = METSalesLine::find(salesLine.RecId, true);
        if (metSalesLine)
        {
            metSalesLine.SubstitutionType = METSalesItemSubstitutionType::None;
            metSalesLine.SubstitutionCode = METSalesItemSubstitutionCode::None;
            metSalesLine.ReasonId = METConstants::NewReasonCode;

            metSalesLine.update();
        }


    }

    container conItemId;
    InventTable inventTable;
    int numberOfLines = 1, numberOfSO = 100;
    int i = 0;
    METSalesOrderTypeID salesOrderType = "Order online";
    ItemId  subsItemId = "998436"; // needs to have stock in corresponding WH, at least 100
    InventOnhand    onHand;
    CustAccount custAccount = "71289183"; // Customer allow subs
    //CustAccount custAccount = "71100355"; // Customer does NOT allow subs

