    InventDim inventDim;

    ttsbegin;

    inventDim.InventSiteId = "HUNTWDALM";
    inventDim.InventLocationId = "025";
    inventDim = InventDim::findOrCreate(inventDim);

    onHandDimParm.initFromInventDim(inventDim);

    createSalesOrderTypes(salesOrderType);
    SalesTable salesTable = createSalesTable(custAccount, salesOrderType, inventDim);

    for (int j = 0; j < numberOfSO; j++)
    {
        createSalesLine(salesTable, subsItemId);
        // create SO header

